"""v1 baseline: fault plans generated by Hypothesis, run through a planning session.

Hypothesis writes ``base: random`` plans in the same space a planner uses
(message keys from the protocol description, values within the profile, at
most ``max_faults`` faults and disconnects), and every plan goes through a
:class:`~replayspect.session.Session`. Seeds, bound checks and the run count are
therefore exactly those of a planner session: run ``i`` uses ``seed_base + i``.

Hypothesis only generates here. It never sees a failure: it would replay a
failing example to confirm it, and the replay would get the session's next
seed, so the outcome is not a function of the plan (Hypothesis reports that as
flaky, and every replay uses up a run). The session records the first
violation instead, and later examples return without running. Shrinking is
left to :mod:`replayspect.shrink`.

Hypothesis also mixes integer constants found in local source modules into
what it draws (a few percent of draws). Here that would include the timing
constants of the system under test, which a planner never sees, and it would
make generation depend on the source and on how replayspect is installed.
:func:`hyp_search` turns it off for its own runs. There is no public setting for
this, so it patches a private hook and fails loudly if the hook is gone.

Requires the optional ``hypothesis`` package (``pip install -e ".[hyp]"``).
Generated plans depend on the Hypothesis version as well as its seed, so
results record the version.
"""

from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Any, Iterator

from hypothesis import HealthCheck, Phase, given, settings
from hypothesis import __version__ as HYPOTHESIS_VERSION
from hypothesis import seed as hyp_seed_decorator
from hypothesis import strategies as st
from hypothesis.internal.constants_ast import Constants

from replayspect.runner import PlanVocabulary, System, get_system
from replayspect.session import Session, SessionConfig

#: Delays do not count against ``max_faults``; this caps them so plans stay readable.
MAX_DELAYS = 10
#: Upper bound on the gap before each generated disconnect.
MAX_DISCONNECT_GAP_US = 30_000_000


@contextmanager
def no_local_constants() -> Iterator[None]:
    """Stop Hypothesis drawing constants from local source modules (see the module docstring)."""
    from hypothesis.internal.conjecture import providers

    if not (callable(getattr(providers, "_get_local_constants", None)) and hasattr(providers, "CONSTANTS_CACHE")):
        raise RuntimeError(
            f"hypothesis {HYPOTHESIS_VERSION} has no _get_local_constants hook; generated plans would "
            "depend on local source constants. Update replayspect.hyp for this version."
        )
    original, empty = providers._get_local_constants, Constants()
    providers._get_local_constants = lambda: empty
    providers.CONSTANTS_CACHE.cache.clear()
    try:
        yield
    finally:
        providers._get_local_constants = original
        providers.CONSTANTS_CACHE.cache.clear()


def _key(d: dict[str, Any]) -> tuple[Any, ...]:
    return (d["dir"], d["msg"], d["req_id"], d["k"])


def message_keys(vocab: PlanVocabulary) -> st.SearchStrategy[dict[str, Any]]:
    """A message key from the vocabulary: half command traffic, half polls."""

    @st.composite
    def key(draw: st.DrawFn) -> dict[str, Any]:
        direction = draw(st.sampled_from(["c2s", "s2c"]))
        if draw(st.booleans()):
            req_id, request = draw(st.sampled_from(vocab.commands))
            msg = request if direction == "c2s" else draw(st.sampled_from(vocab.command_replies))
        else:
            req_id = draw(st.sampled_from(vocab.polls))
            msg = vocab.poll_request if direction == "c2s" else vocab.poll_reply
        return {"dir": direction, "msg": msg, "req_id": req_id, "k": draw(st.integers(0, vocab.max_k))}

    return key()


def plans(system: System, max_faults: int = 20) -> st.SearchStrategy[dict[str, Any]]:
    """Plans that always pass the session's checks for ``system``."""
    if system.vocabulary is None:
        raise ValueError(f"system {system.name} has no plan vocabulary")
    vocab, p = system.vocabulary, system.profile
    keys = message_keys(vocab)

    def fault(k: dict[str, Any]) -> st.SearchStrategy[dict[str, Any]]:
        lo, hi = getattr(p, k["dir"]).dup_extra_us
        return st.one_of(st.just({**k, "drop": True}), st.integers(lo, hi).map(lambda x: {**k, "dup_extra_us": x}))

    def delay(k: dict[str, Any]) -> st.SearchStrategy[dict[str, Any]]:
        lo, hi = getattr(p, k["dir"]).delay_us
        return st.integers(lo, hi).map(lambda x: {**k, "delay_us": x})

    @st.composite
    def plan(draw: st.DrawFn) -> dict[str, Any]:
        faults = draw(st.lists(keys.flatmap(fault), max_size=max_faults, unique_by=_key))
        # Disconnects are laid out one after another so they never overlap.
        disconnects: list[dict[str, int]] = []
        t = 0
        gaps = st.tuples(st.integers(1, MAX_DISCONNECT_GAP_US), st.integers(*p.disconnect_duration_us))
        for gap, duration in draw(st.lists(gaps, max_size=max_faults - len(faults))):
            t += gap
            if t >= system.until_us:
                break
            disconnects.append({"t_us": t, "duration_us": duration})
            t += duration
        delays = draw(st.lists(keys.flatmap(delay), max_size=MAX_DELAYS, unique_by=_key))
        return {"base": "random", "delays": delays, "faults": faults, "disconnects": disconnects}

    return plan()


@dataclass
class HypResult:
    hyp_seed: int
    seed_base: int
    budget: int
    runs: int
    first_violation_run: int | None
    violated: list[str]  # contracts violated in the first violating run
    rejected: int
    entries: int  # plan entries in all runs
    no_effect_entries: int
    hypothesis_version: str = HYPOTHESIS_VERSION
    plans: list[dict[str, Any]] = field(default_factory=list, repr=False)

    @property
    def runs_to_first_violation(self) -> int | None:
        return None if self.first_violation_run is None else self.first_violation_run + 1


def hyp_search(
    mutants: tuple[str, ...] | list[str],
    seed_base: int = 0,
    budget: int = 100,
    hyp_seed: int = 0,
    system: str = "lift.v0",
    max_faults: int = 20,
) -> HypResult:
    """Run Hypothesis-generated plans until the first violation or the budget runs out."""
    s = Session(SessionConfig(system, tuple(mutants), seed_base, budget, max_faults), None)
    res = HypResult(hyp_seed, seed_base, budget, 0, None, [], 0, 0, 0)

    @hyp_seed_decorator(hyp_seed)
    @settings(
        max_examples=budget, phases=[Phase.generate], database=None, deadline=None,
        suppress_health_check=list(HealthCheck),
    )
    @given(plans(s.system, max_faults))
    def run(plan: dict[str, Any]) -> None:
        if s.first_violation_run is not None or s.used >= budget:
            return
        out = s.run_plan(plan)
        res.plans.append(plan)
        res.entries += len(plan["delays"]) + len(plan["faults"]) + len(plan["disconnects"])
        if out["status"] == "rejected":
            res.rejected += 1
            return
        res.no_effect_entries += sum(len(v) for v in out["no_effect"].values())
        if out["violations"] and not res.violated:
            res.violated = sorted({v["contract"] for v in out["violations"]})

    with no_local_constants():
        run()
    res.runs, res.first_violation_run = s.used, s.first_violation_run
    return res
